package com.malikoil.intelligence
import org.junit.Assert.*
import org.junit.Test
import java.time.*
import java.util.zip.ZipInputStream
import java.io.File
class DailyRateReportTest{
 private val now=Instant.parse("2026-11-07T14:00:00Z").toEpochMilli()
 private fun row(id:String,day:String,amount:String="8000",grade:String="standard",source:String="TEST SYNTHETIC - not a real rate")=ReviewedRate(id,"sarson","Samundri",grade,amount,"40kg",Instant.parse(day+"T05:00:00Z").epochSecond,source,"fixture-event",now-1000)
 @Test fun sixPmUsesKarachiTime(){assertEquals(Instant.parse("2026-11-07T13:00:00Z"),DailyRateReport.nextSix(Instant.parse("2026-11-07T12:59:59Z")));assertEquals(Instant.parse("2026-11-08T13:00:00Z"),DailyRateReport.nextSix(Instant.parse("2026-11-07T13:00:00Z")))}
 @Test fun changesRequireSameMarketGradeAndSource(){val previous=row("old","2026-11-06");val current=row("now","2026-11-07","8240");val different=row("different","2026-11-07","9000",source="Other TEST source");val report=DailyRateReport.build(LocalDate.parse("2026-11-07"),now,"roman",listOf(previous,current,different),emptyList(),"sarson");assertEquals(2,report.rates.size);assertEquals("3.00",report.rates.first{it.rate.id=="now"}.changePercent!!.toPlainString());assertNull(report.rates.first{it.rate.id=="different"}.previous);assertTrue(report.summary.contains("PKR 8240.00/40kg"));assertTrue(report.summary.contains("+3.00%"))}
 @Test fun missingDayIsNotFilledWithOldRate(){val report=DailyRateReport.build(LocalDate.parse("2026-11-07"),now,"en",listOf(row("old","2026-11-06")),emptyList(),"sarson");assertTrue(report.rates.isEmpty());assertTrue(report.summary.contains("No owner-reviewed rate"));assertEquals(1,report.history.size)}
 @Test fun emptyWorkbookContainsNoInventedChart(){val report=DailyRateReport.build(LocalDate.parse("2026-11-07"),now,"ur",emptyList(),emptyList(),"sarson");val zip=ZipInputStream(DailyWorkbook.write(report).inputStream());val names=mutableListOf<String>();while(true){val entry=zip.nextEntry?:break;names.add(entry.name)};assertFalse(names.contains("xl/charts/chart1.xml"));assertTrue(names.contains("xl/worksheets/sheet4.xml"))}
 @Test fun workbookPreservesFormulaSafetyDatesAndChart(){val report=DailyRateReport.build(LocalDate.parse("2026-11-07"),now,"roman",listOf(row("old","2026-11-06"),row("now","2026-11-07","8240")),listOf(CapturedGroupMessage("fixture-message","TEST GROUP","sarson fixture only, no real rate",now,now)),"sarson");val bytes=DailyWorkbook.write(report);val parts=mutableMapOf<String,String>();ZipInputStream(bytes.inputStream()).use{zip->while(true){val entry=zip.nextEntry?:break;parts[entry.name]=String(zip.readBytes())}};assertTrue(parts.getValue("xl/charts/chart1.xml").contains("dispBlanksAs val=\"gap\""));assertTrue(parts.getValue("xl/worksheets/sheet2.xml").contains("IF(G2="));assertTrue(parts.getValue("xl/worksheets/sheet2.xml").contains("<v>0.03</v>"));val output=File("build/test-artifacts/report-fixture.xlsx");output.parentFile!!.mkdirs();output.writeBytes(bytes);val unsafe=DailyRateReport.build(LocalDate.parse("2026-11-07"),now,"en",listOf(row("unsafe","2026-11-07",source="=HYPERLINK(\"https://invalid.test\")")),emptyList(),"sarson");val safe=DailyWorkbook.write(unsafe);val texts=mutableListOf<String>();ZipInputStream(safe.inputStream()).use{zip->while(zip.nextEntry!=null)texts.add(String(zip.readBytes()))};assertTrue(texts.any{it.contains("=HYPERLINK(&quot;")});assertFalse(texts.any{it.contains("<f>=HYPERLINK")})}
}
